# Shared leg library: small, named, reusable skills.
# Players import from here; add a NEW leg only when no existing leg fits.

from collections import deque

from perception import connected_components


PROTOCOL_ROWS = {
    "D": (0, 1),
    "U": (0, 5),
    "L": (1, 5),
    "R": (1,),
    "M": (0, 3),
}


def find_right_segment_panel(frame):
    """Return the segments and lattice coordinates of the right-hand panel."""
    width = len(frame[0])
    segments = [
        blob
        for blob in connected_components(frame, colors=(1, 5), min_area=3)
        if blob.area == 3
        and 1 in blob.size
        and blob.centroid[1] > width / 2
    ]
    rows = sorted({int(round(blob.centroid[0])) for blob in segments})
    cols = sorted({int(round(blob.centroid[1])) for blob in segments})
    return segments, rows, cols


def find_upper_right_board_objects(frame):
    """Return color-11 board objects in the upper-right play area."""
    height, width = len(frame), len(frame[0])
    return [
        blob
        for blob in connected_components(frame, colors=(11,), min_area=4)
        if blob.bbox[2] < height / 2 and blob.bbox[1] > width / 2
    ]


def write_protocol_to_segment_panel(env, frame, rows, cols, protocol):
    """Set panel columns to the six-row glyph for each protocol symbol."""
    for col_index, direction in enumerate(protocol):
        desired_rows = PROTOCOL_ROWS[direction]
        for row_index, row in enumerate(rows):
            is_on = int(frame[row][cols[col_index]]) == 5
            should_be_on = row_index in desired_rows
            if is_on != should_be_on:
                env.step(6, cols[col_index], row)


def click_largest_color_9_submit_disc(env, frame=None):
    """Click the largest two-dimensional color-9 disc."""
    if frame is None:
        frame = env.frame()
    submit_discs = [
        blob
        for blob in connected_components(frame, colors=(9,), min_area=4)
        if blob.size[0] > 1 and blob.size[1] > 1
    ]
    if submit_discs:
        disc = max(submit_discs, key=lambda blob: blob.area)
        row, col = disc.centroid
        env.step(6, int(round(col)), int(round(row)))


def make_small_segments_color_5(env):
    """Toggle each small color-1 line segment."""
    segments = [
        blob
        for blob in connected_components(env.frame(), colors=(1,), min_area=3)
        if blob.area == 3 and 1 in blob.size
    ]
    for blob in segments:
        row, col = blob.centroid
        env.step(6, int(round(col)), int(round(row)))


def turn_on_outer_rows_of_right_segment_panel(env):
    """Turn on the top and bottom rows of the right segment panel."""
    frame = env.frame()
    segments, _, _ = find_right_segment_panel(frame)
    if not segments:
        return None

    rows = [blob.centroid[0] for blob in segments]
    outer_rows = (min(rows), max(rows))
    for blob in segments:
        if blob.color == 1 and any(
            abs(blob.centroid[0] - row) < 0.5 for row in outer_rows
        ):
            row, col = blob.centroid
            env.step(6, int(round(col)), int(round(row)))
    return frame


def encode_reacquisition_route_through_barrier(env):
    """Route the small cyan agent through a wall gap and encode the route."""
    frame = env.frame()
    height, width = len(frame), len(frame[0])

    _, rows, cols = find_right_segment_panel(frame)

    board_objects = find_upper_right_board_objects(frame)
    sources = [
        blob for blob in board_objects if blob.area == 14 and blob.size == (4, 4)
    ]
    targets = [blob for blob in board_objects if blob not in sources]
    if len(rows) != 6 or not cols or not sources or not targets:
        return False

    source = sources[0]
    target = max(targets, key=lambda blob: blob.area)
    step = source.size[0]
    source_row, source_col = source.top_left

    def snap_to_lattice(value, origin):
        return origin + int(round((value - origin) / step)) * step

    target_row = snap_to_lattice(target.centroid[0], source_row)
    target_col = snap_to_lattice(target.centroid[1], source_col)

    barriers = [
        blob
        for blob in connected_components(frame, colors=(6,), min_area=step * step)
        if blob.bbox[2] < height / 2
    ]
    route = []

    def add_axis_moves(start, end, negative, positive):
        direction = negative if end < start else positive
        route.extend(direction for _ in range(abs(end - start) // step))

    separating = []
    for barrier in barriers:
        barrier_col = snap_to_lattice(barrier.centroid[1], source_col)
        if min(source_col, target_col) < barrier_col < max(source_col, target_col):
            separating.append((barrier_col, barrier))

    if separating:
        wall_col = separating[0][0]
        wall_top = min(blob.bbox[0] for _, blob in separating)
        wall_bottom = max(blob.bbox[2] for _, blob in separating)
        first_lattice_row = snap_to_lattice(wall_top, source_row)
        gap_rows = []
        for row in range(first_lattice_row, wall_bottom + 1, step):
            wall_pixels = sum(
                int(frame[r][c]) == 6
                for r in range(row, row + step)
                for c in range(wall_col, wall_col + step)
            )
            if wall_pixels == 0:
                gap_rows.append(row)
        if not gap_rows:
            return False
        gap_row = min(
            gap_rows,
            key=lambda row: abs(source_row - row) + abs(target_row - row),
        )
        add_axis_moves(source_row, gap_row, "U", "D")
        add_axis_moves(source_col, target_col, "L", "R")
        add_axis_moves(gap_row, target_row, "U", "D")
    else:
        add_axis_moves(source_col, target_col, "L", "R")
        add_axis_moves(source_row, target_row, "U", "D")

    if len(route) != len(cols):
        return False

    write_protocol_to_segment_panel(env, frame, rows, cols, route)
    return True


def reacquire_max_scaled_agent_and_route_to_socket(env):
    """Collapse a scaled agent and route one lattice cell at a time."""
    frame = env.frame()
    height, width = len(frame), len(frame[0])

    _, rows, cols = find_right_segment_panel(frame)
    if len(rows) != 6 or not cols:
        return False

    board_tiles = [
        blob
        for blob in connected_components(frame, colors=(4,), min_area=9)
        if blob.bbox[2] < height / 2
        and blob.bbox[1] > width / 2
        and blob.size[0] == blob.size[1]
        and blob.area == blob.size[0] * blob.size[1]
    ]
    if not board_tiles:
        return False
    step = min(blob.size[0] for blob in board_tiles)

    board_objects = find_upper_right_board_objects(frame)
    sources = [
        blob
        for blob in board_objects
        if blob.size[0] == blob.size[1] and blob.size[0] >= step
    ]
    targets = [blob for blob in board_objects if blob not in sources]
    if not sources or not targets:
        return False

    source = max(sources, key=lambda blob: blob.area)
    target = max(targets, key=lambda blob: blob.area)
    scale = source.size[0] // step
    reacquisitions = max(0, scale - 1)

    start = source.top_left
    destination = (target.bbox[0], target.bbox[1] + 1)
    direction_delta = {
        "L": (0, -step),
        "R": (0, step),
        "U": (-step, 0),
        "D": (step, 0),
    }

    horizontal = ("L", "R") if destination[1] < start[1] else ("R", "L")
    vertical = ("U", "D") if destination[0] < start[0] else ("D", "U")
    direction_order = horizontal + vertical

    def walkable(position):
        row, col = position
        if (
            row < 0
            or col <= width / 2
            or row + step > height / 2
            or col + step > width
        ):
            return False
        return all(
            int(frame[r][c]) not in (0, 6)
            for r in range(row, row + step)
            for c in range(col, col + step)
        )

    queue = deque([(start, [])])
    seen = {start}
    route = None
    while queue:
        position, path = queue.popleft()
        if position == destination:
            route = path
            break
        if len(path) >= len(cols) - reacquisitions:
            continue
        for direction in direction_order:
            dr, dc = direction_delta[direction]
            neighbor = (position[0] + dr, position[1] + dc)
            if neighbor in seen or not walkable(neighbor):
                continue
            seen.add(neighbor)
            queue.append((neighbor, path + [direction]))

    protocol = ["M"] * reacquisitions + (route or [])
    if route is None or len(protocol) != len(cols):
        return False

    write_protocol_to_segment_panel(env, frame, rows, cols, protocol)
    return True
"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def frame_delta(before, after) -> dict:
    a, b = arr(before), arr(after)
    ys, xs = np.where(a != b)
    if len(ys) == 0:
        return {"count": 0, "bbox": None, "samples": []}
    samples = [(int(y), int(x), int(a[y, x]), int(b[y, x])) for y, x in zip(ys[:80], xs[:80])]
    return {
        "count": int(len(ys)),
        "bbox": (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max())),
        "samples": samples,
    }


def action_deltas(env, actions: Sequence[int] = ACTIONS) -> Dict[int, dict]:
    base = arr(env.frame()).copy()
    out = {}
    for action in actions:
        clone = env.clone()
        clone.step(action)
        out[int(action)] = frame_delta(base, clone.frame())
    return out


def replay(env, actions: Sequence[int]):
    clone = env.clone()
    for action in actions:
        if clone.terminal():
            break
        clone.step(int(action))
    return clone


def path_result(env, actions: Sequence[int]) -> dict:
    clone = replay(env, actions)
    return {
        "levels_completed": int(clone.levels_completed),
        "terminal": bool(clone.terminal()),
        "path_len": len(actions),
        "colors": color_counts(clone.frame()),
        "objects": object_candidates(clone.frame()),
    }


def changed_signature(env, actions: Sequence[int], cell: int = 4):
    before = block_signatures(env.frame(), cell)
    clone = replay(env, actions)
    after = block_signatures(clone.frame(), cell)
    return {k: (before.get(k), after.get(k)) for k in sorted(set(before) | set(after))
            if before.get(k) != after.get(k)}


def bounded_bfs(env, goal_fn, actions: Sequence[int] = (UP, DOWN, LEFT, RIGHT, USE),
                key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Generic clone BFS over observational keys. Use small max_states first."""
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()
    start_key = key_fn(env)
    q = deque([(env.clone(), [])])
    seen = {start_key}
    while q and len(seen) <= max_states:
        node, path = q.popleft()
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth:
            continue
        for action in actions:
            child = node.clone()
            child.step(int(action))
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            q.append((child, path + [int(action)]))
    return None


def bounded_replay_bfs(env, goal_fn, action_fn,
                       key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Path-only BFS for games whose deep Arena clones become expensive.

    The queue retains compact action paths, not recursively deep-copied runtime
    states. Each node is reconstructed from one root clone. ``action_fn(node)``
    may return integer actions or coordinate tuples such as ``(6, x, y)``.
    """
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()

    def reconstruct(path):
        node = env.clone()
        for action in path:
            if isinstance(action, tuple):
                node.step(*action)
            else:
                node.step(int(action))
        return node

    start = reconstruct([])
    q = deque([[]])
    seen = {key_fn(start)}
    while q and len(seen) <= max_states:
        path = q.popleft()
        node = reconstruct(path)
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth or node.terminal():
            continue
        for action in action_fn(node):
            child_path = path + [action]
            child = reconstruct(child_path)
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            if goal_fn(child, child_path):
                return child_path
            q.append(child_path)
    return None


def level_goal(base_level: int):
    return lambda env, path: env.levels_completed > base_level

