    rows, columns = segment_geometry(frame)
    bits = tuple(
        "".join("1" if int(frame[row, col]) == 5 else "0" for row in rows)
        for col in columns
    )
    demo = tuple(
        (blob.color, blob.bbox, blob.area, normalized_shape(frame, blob))
        for blob in connected_components(frame, colors=(4,))
        if blob.bbox[1] < 31
    )
